node --input-type=module -e "
import { loadEnv, botToken, AVA_BOT_APP_ID, DISCORD_API } from './src/config.mjs';
import { authHeaders } from './src/discordApi.mjs';

const CHANNEL = '1520665313631408251';
const env = await loadEnv();
const token = botToken(env);
const avaId = AVA_BOT_APP_ID;
const headers = authHeaders(token);
const res = await fetch(DISCORD_API + '/channels/' + CHANNEL + '/messages?limit=40', { headers });
if (!res.ok) { console.error('FAIL', res.status, await res.text()); process.exit(1); }
const msgs = await res.json();
// chronological oldest first for reading
const ordered = [...msgs].reverse();
for (const m of ordered) {
  const ts = m.timestamp?.slice(0, 19)?.replace('T',' ');
  const author = m.author?.username || '?';
  const bot = m.author?.bot ? ' [bot]' : '';
  const id = m.id;
  const ref = m.message_reference?.message_id ? ' ref:'+m.message_reference.message_id : '';
  const reacts = (m.reactions||[]).map(r => (r.emoji?.name||'?')+'x'+r.count).join(' ') || '-';
  const mentionsAva = (m.mentions||[]).some(u => u.id === avaId) || new RegExp('<@!?'+avaId+'>').test(m.content||'');
  const softAva = /\\bava(\\s+ivy)?\\b/i.test(m.content||'');
  const content = String(m.content||'').replace(/\\n/g,' | ').slice(0, 280);
  const flag = (mentionsAva || softAva) && !m.author?.bot ? ' ***AVA-ADDR***' : '';
  console.log('---');
  console.log(ts, author+bot, id+ref+flag);
  console.log('reacts:', reacts);
  console.log(content || '(empty/embed)');
}
console.log('\\nAVA_ID', avaId, 'count', msgs.length);
"

node --input-type=module -e "
import { loadEnv, botToken, AVA_BOT_APP_ID, DISCORD_API } from './src/config.mjs';
import { authHeaders } from './src/discordApi.mjs';

const CHANNEL = '1520665313631408251';
const env = await loadEnv();
const headers = authHeaders(botToken(env));
const avaId = AVA_BOT_APP_ID;

// fetch newest 15 with full detail
const res = await fetch(DISCORD_API + '/channels/' + CHANNEL + '/messages?limit=15', { headers });
const msgs = await res.json();
for (const m of msgs) {
  const embeds = (m.embeds||[]).map(e => ({title:e.title, desc:(e.description||'').slice(0,120), url:e.url, image:e.image?.url||e.thumbnail?.url}));
  const atts = (m.attachments||[]).map(a => a.filename+':'+a.url);
  console.log(JSON.stringify({
    id: m.id,
    ts: m.timestamp,
    author: m.author?.username,
    authorId: m.author?.id,
    bot: !!m.author?.bot,
    content: m.content,
    ref: m.message_reference?.message_id,
    reacts: (m.reactions||[]).map(r => r.emoji?.name),
    embeds,
    atts,
    mentions: (m.mentions||[]).map(u => u.username+':'+u.id),
  }, null, 2));
  console.log('====');
}

// check if Ava replied after solar praise
const praiseId = '1533627859254640813';
const embedId = '1533627703532585082';
const afterPraise = msgs.filter(m => BigInt(m.id) > BigInt(praiseId) && m.author?.id === avaId);
const afterEmbed = msgs.filter(m => BigInt(m.id) > BigInt(embedId) && m.author?.id === avaId);
console.log('ava after praise', afterPraise.map(m=>m.id));
console.log('ava after embed', afterEmbed.map(m=>m.id+':'+(m.content||'').slice(0,80)));
"

node --input-type=module -e "
import fs from 'node:fs';
import { loadEnv, botToken, DISCORD_API } from './src/config.mjs';
import { authHeaders } from './src/discordApi.mjs';
const env = await loadEnv();
const headers = authHeaders(botToken(env));
const urls = [
  ['shot1.png', 'https://cdn.discordapp.com/attachments/1520665313631408251/1533627703280799774/image.png'],
  ['shot2.png', 'https://cdn.discordapp.com/attachments/1520665313631408251/1533627858952392714/image.png'],
];
for (const [name, url] of urls) {
  const r = await fetch(url, { headers: { Authorization: headers.Authorization } });
  if (!r.ok) { console.log('fail', name, r.status); continue; }
  const buf = Buffer.from(await r.arrayBuffer());
  fs.writeFileSync('data/_tmp-' + name, buf);
  console.log('saved', name, buf.length);
}
"

